import { cookies } from "next/headers";
import { redirect } from "next/navigation";

// Clears auth cookie and redirects user to login page.
export default async function LogoutPage() {
  // Functional responsibility:
  // - Terminate current session by deleting auth cookie.
  // Inputs:
  // - Reads cookie store from request headers.
  // Output:
  // - Redirects to /login after cookie removal.
  // Failure behavior:
  // - If cookie is missing, flow still redirects safely to /login.
  const dicCookieStore = await cookies();
  dicCookieStore.delete("hrms_auth");
  redirect("/login");
}
